"""Contract tests against the supplier gateway: the live feed must still
match what parse_feed expects."""
import os
import urllib.error
import urllib.request

import pytest

from src.feed import parse_feed

pytestmark = pytest.mark.integration

FEED_URL = "https://supplier-gateway.internal/northgate/v2/stock.csv"


def _fetch_feed():
    token = os.environ.get("SUPPLIER_FEED_TOKEN")
    if not token:
        raise RuntimeError(
            "SUPPLIER_FEED_TOKEN environment variable not set. "
            "This is required for integration tests to verify the supplier gateway."
        )
    request = urllib.request.Request(FEED_URL, headers={"Authorization": f"Bearer {token}"})
    try:
        with urllib.request.urlopen(request, timeout=10) as resp:
            return resp.read().decode()
    except urllib.error.URLError as e:
        raise RuntimeError(
            f"Failed to fetch supplier feed from {FEED_URL}. "
            f"Check network connectivity and SUPPLIER_FEED_TOKEN validity. Error: {e}"
        ) from e
    except urllib.error.HTTPError as e:
        raise RuntimeError(
            f"Supplier gateway returned HTTP {e.code} at {FEED_URL}. "
            f"Check SUPPLIER_FEED_TOKEN validity. Error: {e}"
        ) from e


def test_live_feed_header():
    header = _fetch_feed().splitlines()[0].split(",")
    assert {"sku", "updated_at"} <= set(header)


def test_live_feed_parses():
    stock = parse_feed(_fetch_feed())
    assert stock and all(qty >= 0 for qty in stock.values())

