"""Parser for the supplier's stock feed (CSV, one row per SKU)."""
import csv
import io


def parse_feed(text):
    rows = csv.DictReader(io.StringIO(text))
    if rows is None:
        raise ValueError("Invalid CSV format")

    result = {}
    for row in rows:
        if row is None:
            continue
        if "sku" not in row:
            raise ValueError("Feed is missing 'sku' column")
        if "available" not in row:
            raise ValueError("Feed is missing 'available' column")

        sku = row["sku"].strip()
        try:
            available = int(row["available"])
        except (ValueError, TypeError) as e:
            raise ValueError(f"Invalid 'available' value for SKU {sku}: {row['available']}") from e

        result[sku] = available

    return result

