import csv
import io


def parse_feed(text):
    rows = csv.DictReader(io.StringIO(text))
    if rows is None:
        raise ValueError("Invalid CSV format")

    result = {}
    for row in rows:
        if row is None:
            continue
        if "sku" not in row:
            raise ValueError("Feed is missing 'sku' column")

        # Handle both "available" and "qty" column names for compatibility
        qty_column = None
        if "available" in row:
            qty_column = "available"
        elif "qty" in row:
            qty_column = "qty"
        elif "quantity" in row:
            qty_column = "quantity"

        if qty_column is None:
            raise ValueError("Feed is missing 'available' column (or 'qty'/'quantity')")

        sku = row["sku"].strip()
        try:
            available = int(row[qty_column])
        except (ValueError, TypeError) as e:
            raise ValueError(f"Invalid quantity value for SKU {sku}: {row[qty_column]}") from e

        result[sku] = available

    return result

